import{_ as d,o as t,c as s,a2 as a}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"ビルドとパッケージング","description":"同じコードから四つの形を作れます。ローカルサーバー付きのブラウザー版、単体サーバー、Electron デスクトップ版、そして別リポジトリの静的オンライン版です。ここではコマンドと、コードを変えるときに実際に効いてくる違いをまとめます。","frontmatter":{"description":"同じコードから四つの形を作れます。ローカルサーバー付きのブラウザー版、単体サーバー、Electron デスクトップ版、そして別リポジトリの静的オンライン版です。ここではコマンドと、コードを変えるときに実際に効いてくる違いをまとめます。"},"headers":[],"relativePath":"ja/development/build.md","filePath":"ja/development/build.md","lastUpdated":1794782163000}'),i={name:"ja/development/build.md"};function o(c,e,n,r,l,p){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="ビルドとパッケージング" tabindex="-1">ビルドとパッケージング <a class="header-anchor" href="#ビルドとパッケージング" aria-label="Permalink to &quot;ビルドとパッケージング&quot;">​</a></h1><p>同じコードから四つの形を作れます。ローカルサーバー付きのブラウザー版、単体サーバー、Electron デスクトップ版、そして別リポジトリの静的オンライン版です。ここではコマンドと、コードを変えるときに実際に効いてくる違いをまとめます。</p><h2 id="必要なもの" tabindex="-1">必要なもの <a class="header-anchor" href="#必要なもの" aria-label="Permalink to &quot;必要なもの&quot;">​</a></h2><ul><li>Node.js 22 以上と npm。</li><li>バッチ CLI は Node の TypeScript 対応に依存します。Node 22.6–23.5 では <code>--experimental-strip-types</code> が必要、Node 23.6 以降は既定で有効、Node 26 なら <code>.ts</code> の入口をそのまま実行できます。</li><li>デスクトップのパッケージングは既定で Windows x64（<code>electron-builder.yml</code>）。サーバー自体は Node が動く環境ならどこでも動きます。</li></ul><h2 id="コマンド" tabindex="-1">コマンド <a class="header-anchor" href="#コマンド" aria-label="Permalink to &quot;コマンド&quot;">​</a></h2><table tabindex="0"><thead><tr><th>コマンド</th><th>内容</th><th>出力</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td>Vite 開発サーバーと API ミドルウェアを <code>127.0.0.1:5173</code> で起動（使用中なら次の空きポート）。</td><td>なし</td></tr><tr><td><code>npm run build</code></td><td>型検査とフロントエンドのビルド。</td><td><code>dist/</code></td></tr><tr><td><code>npm run preview</code></td><td>同じ API ミドルウェアでビルド結果をプレビュー。</td><td>—</td></tr><tr><td><code>npm run server:build</code></td><td>esbuild で <code>server/app.ts</code> と <code>server/standalone.ts</code> を束ねる。</td><td><code>dist-server/app.mjs</code>、<code>dist-server/standalone.mjs</code></td></tr><tr><td><code>npm start</code></td><td>束ねた単体サーバーを実行。</td><td><code>127.0.0.1:3921</code></td></tr><tr><td><code>npm run desktop</code></td><td>ビルド、サーバー束ね、Electron 起動。</td><td>ウィンドウ</td></tr><tr><td><code>npm run dist:win</code></td><td>NSIS インストーラーとポータブル版。</td><td><code>release/</code></td></tr><tr><td><code>npm run dist:dir</code></td><td>未パッケージのフォルダー。デスクトップ版の確認用。</td><td><code>release/win-unpacked/</code></td></tr><tr><td><code>npm run docker:up</code></td><td>コンテナをビルドして起動（ローカルフォルダーをマウント）。</td><td><code>http://127.0.0.1:3921</code></td></tr><tr><td><code>npm run docs:dev</code></td><td>ドキュメントの開発サーバー。サイトルートで配信（<code>DOCS_BASE=/</code>）。</td><td><code>127.0.0.1:5174</code></td></tr><tr><td><code>npm run docs:build</code></td><td>ドキュメントをビルド。リンク切れがあると失敗。</td><td><code>docs/.vitepress/dist/</code></td></tr></tbody></table><h2 id="ローカル開発" tabindex="-1">ローカル開発 <a class="header-anchor" href="#ローカル開発" aria-label="Permalink to &quot;ローカル開発&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>別プロセスは不要です。<code>server/plugin.ts</code> が <code>createMangaHandler</code> を Vite のミドルウェアとして <code>configureServer</code> と <code>configurePreviewServer</code> の両方に差し込みます。<code>/api/library</code> はページと同じイベントループで処理されるので、サーバー側の <code>console.log</code> は Vite を動かしているターミナルに出ます。</p><p>フロントエンドは Vite が <code>src/</code> から配信し、サーバーはリポジトリ直下の <code>raw/</code> と <code>data/</code> を読み書きします。</p><h2 id="本番ビルド" tabindex="-1">本番ビルド <a class="header-anchor" href="#本番ビルド" aria-label="Permalink to &quot;本番ビルド&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p><code>npm run build</code> は最初に <code>tsc -b</code> を走らせるので、型エラーがあればそこで止まります。<code>server:build</code> は <code>platform: node</code>、<code>format: esm</code>、<code>target: node20</code> で束ね、<code>pngjs</code> と <code>jpeg-js</code> が内部で <code>require</code> を呼ぶため <code>createRequire</code> のバナーを差し込みます。</p><p><code>npm start</code> は <code>dist/</code> が存在する前提です。なければ <code>server/standalone.ts</code> が <code>CLI_MISSING_STATIC_DIR</code> で終了します。設定は環境変数だけです。</p><table tabindex="0"><thead><tr><th>変数</th><th>既定値</th><th>用途</th></tr></thead><tbody><tr><td><code>HOST</code></td><td><code>127.0.0.1</code></td><td>待ち受けアドレス。LAN からアクセスさせる場合のみ <code>0.0.0.0</code> にします（認証はありません）。</td></tr><tr><td><code>PORT</code></td><td><code>3921</code></td><td>待ち受けポート。</td></tr><tr><td><code>RAW_DIR</code></td><td><code>&lt;cwd&gt;/raw</code></td><td>漫画画像。</td></tr><tr><td><code>DATA_DIR</code></td><td><code>&lt;cwd&gt;/data</code></td><td>JSON データ。</td></tr><tr><td><code>EXPORT_DIR</code></td><td><code>&lt;cwd&gt;/exports</code></td><td>生成物。</td></tr><tr><td><code>STATIC_DIR</code></td><td><code>&lt;cwd&gt;/dist</code></td><td>ビルド済みフロントエンド。</td></tr><tr><td><code>MANGA_LOCALE</code></td><td>自動</td><td>UI 言語のヒント: <code>en</code>、<code>zh</code>、<code>ja</code>。</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>info</code></td><td><code>debug</code>、<code>info</code>、<code>warn</code>、<code>error</code>。</td></tr></tbody></table><h2 id="デスクトップ" tabindex="-1">デスクトップ <a class="header-anchor" href="#デスクトップ" aria-label="Permalink to &quot;デスクトップ&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:win</span></span></code></pre></div><p><code>electron/main.cjs</code> が <code>dist-server/app.mjs</code> を同一プロセスで読み込み、<code>dist/</code> を配信してウィンドウを開きます。データは同梱しません。初回起動でライブラリのフォルダーを尋ね、<code>%APPDATA%/manga-memo/config.json</code> に記憶します。<code>raw/</code>、<code>data/</code>、<code>exports/</code> は自分の場所に残ります。</p><p>パッケージ設定は <code>electron-builder.yml</code> です。同梱するのは <code>dist/</code>、<code>dist-server/</code>、<code>electron/</code>、<code>package.json</code> だけで、束ねたサーバーが依存を含むため <code>node_modules</code> は入れません。</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>コンテナは <code>dist-server/standalone.mjs</code> を実行し、ホストの <code>raw/</code>、<code>data/</code>、<code>exports/</code> をマウントします。ローカルマシン向けで、アカウントも認証もありません。ポートを外部へ公開しないでください。</p><h2 id="静的オンライン版" tabindex="-1">静的オンライン版 <a class="header-anchor" href="#静的オンライン版" aria-label="Permalink to &quot;静的オンライン版&quot;">​</a></h2><p>静的オンライン版は別プロジェクトです: <code>https://github.com/PayayaKamo/KomaYomi-online</code>。ブラウザーだけで動く部分集合から作られています。ページ形式とプロジェクトファイルの読み込みは共有しますが、フォルダー走査、コマ検出、プラグイン、WebDAV はサーバープロセスが必要なため使えません。保存内容は IndexedDB に入ります。</p><p>機能を足すときは、どちらの形に属するかを最初に決めます。</p><table tabindex="0"><thead><tr><th>変更</th><th>ローカルサーバー版</th><th>静的オンライン版</th></tr></thead><tbody><tr><td>ページ文書へのフィールド追加</td><td><code>shared/</code> とサーバーの正規化を変更。</td><td><code>shared/</code> にあれば動く。</td></tr><tr><td>検出器やプラグインのフック追加</td><td><code>server/detect.ts</code>、<code>server/plugins.ts</code>。</td><td>利用不可。</td></tr><tr><td>ダイアログやビューの追加</td><td><code>src/components/</code>。</td><td>既存 API だけなら移植しやすい。</td></tr><tr><td>ファイルシステム、プロセス、ネットワーク</td><td>サーバーのみ。</td><td>利用不可。</td></tr></tbody></table><h2 id="検出ベースラインの更新" tabindex="-1">検出ベースラインの更新 <a class="header-anchor" href="#検出ベースラインの更新" aria-label="Permalink to &quot;検出ベースラインの更新&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/manga-cli.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regress</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/manga-cli.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regress</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><p>1 つ目は現在のコマ数と <code>scripts/detect-baseline.json</code> を比べ、<code>--update</code> はベースラインを書き換えます。コミット前に差分を確認してください。ベースラインの更新は「新しい数が正しい」と約束する行為です。</p><h2 id="プルリクエストの前" tabindex="-1">プルリクエストの前 <a class="header-anchor" href="#プルリクエストの前" aria-label="Permalink to &quot;プルリクエストの前&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:scan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p><code>i18n:scan</code> は既定で非厳格、CI は <code>src/</code> に増えた中国語の直書きを失敗として扱います。<code>docs:build</code> はリンク切れで失敗するので、三言語のページ名変更の漏れを見つける一番安い方法です。</p>`,32)])])}const F=d(i,[["render",o]]);export{k as __pageData,F as default};
